<template>
  <div class="night-studio">
    <header class="night-nav">
      <RouterLink to="/home" class="night-brand"><span aria-hidden="true">≋</span> Auralis <small>声音叙事工作室</small></RouterLink>
      <div class="nav-right"><span class="sample-status"><i /> 可交互样片</span><RouterLink to="/projects">进入工作台 <el-icon><TopRight /></el-icon></RouterLink></div>
    </header>

    <div class="night-container">
      <section class="night-intro">
        <div><p class="night-kicker">THE DIRECTOR’S CUT / 001</p><h1>让悬念，<em>先被听见。</em></h1><p class="night-subtitle">从一段小说到一场广播剧。审台本、听表演、放入声音。</p></div>
        <div class="intro-cta"><button class="night-primary" :aria-label="playing ? '暂停样片' : '试听完整样片'" :disabled="!ready || loadingAudio || staleLines.length > 0" @click="toggleMix"><el-icon><component :is="playing ? VideoPause : VideoPlay" /></el-icon>{{ loadingAudio ? '准备声音…' : playing ? '暂停样片' : '试听完整样片' }}</button><small>真实合成配音 · {{ formatTime(schedule.duration) }} · 建议佩戴耳机</small></div>
      </section>

      <details class="compact-source"><summary>阅读《雨夜来件》小说原文</summary><p>{{ fixture.source }}</p></details>
      <div class="night-layout">
        <aside class="story-panel">
          <div class="episode-art" aria-hidden="true"><div class="rain-lines" /><div class="door-outline"><i /><b>23:17</b></div><span>EPISODE 01</span><strong>雨夜<br />来件</strong></div>
          <div class="story-copy"><p class="night-kicker">都市悬疑 / 原创短篇</p><h2>{{ fixture.title }}</h2><p>{{ fixture.subtitle }}</p></div>
          <details class="source-detail"><summary>小说原文 <span>{{ fixture.source.length }} 字 <el-icon><ArrowDown /></el-icon></span></summary><p class="source-text">{{ fixture.source }}</p></details>
          <div class="fact-list"><h3>改编时守住的 5 个事实</h3><p v-for="fact in fixture.facts" :key="fact"><el-icon><Check /></el-icon>{{ fact }}</p></div>
          <div class="story-foot"><span>样片为导演审定稿，音频已预生成。修改即时保存在当前浏览器。</span><button aria-label="导出台本 JSON" @click="downloadScript"><el-icon><Download /></el-icon> 导出台本 JSON</button><button aria-label="还原样片" @click="resetLocal"><el-icon><RefreshLeft /></el-icon> 还原样片</button></div>
        </aside>

        <main class="director-panel">
          <ProductionSteps v-model="activeTab" :steps="tabs" />

          <section v-if="activeTab === 'script'" class="script-view">
            <header class="section-heading"><div><p class="night-kicker">SCRIPT & PERFORMANCE</p><h2>每一句，都有目的。</h2></div><span class="quiet-badge">{{ lines.length }} 句 · 3 个声音</span></header>
            <div class="version-bar"><span>整场表演</span><div class="segmented"><button :class="{ selected: allDirected }" :disabled="!ready" @click="setAllTakes('directed')">导演指导版</button><button :class="{ selected: allNeutral }" :disabled="!hasAllNeutral" @click="setAllTakes('neutral')">无指导对照</button></div><small>同一模型 · 同一音色 · 同一台词</small></div>
            <div class="script-scroll">
              <article v-for="line in lines" :key="line.id" class="script-row" :class="{ selected: selectedLineId === line.id, speaking: currentLineId === line.id && playing }" :style="{ '--actor': role(line.role).color }">
                <button class="line-index" :aria-label="`选择第 ${line.id} 句，添加音效`" :aria-pressed="selectedLineId === line.id" @click="selectedLineId = line.id">{{ line.id }}</button>
                <div class="script-line-content"><div class="actor-name"><strong>{{ role(line.role).name }}</strong><span>{{ line.beat }}</span><small v-if="isStale(line)" class="stale-label">已修改 · 需要重新配音</small></div>
                  <textarea v-model="line.text" :aria-label="`第 ${line.id} 句台词`" rows="2" @input="stopPlayback" @focus="selectedLineId = line.id" />
                  <div class="line-direction"><el-icon><Microphone /></el-icon><span>{{ line.direction }}</span></div>
                  <div v-if="lineCues(line.id).length" class="inline-cues"><button v-for="cue in lineCues(line.id)" :key="cue.id" @click="selectedLineId = line.id; inspectorTab = 'sound'"><el-icon><Headset /></el-icon>{{ placementLabel(cue.placement) }} · {{ cue.label }}</button></div>
                  <button v-if="isStale(line)" class="text-action" @click="restoreLine(line)">还原本句并恢复试听</button>
                </div>
                <div class="line-controls"><button class="icon-play" :aria-label="`试听第 ${line.id} 句`" :disabled="!ready || loadingAudio || isStale(line)" @click="previewLine(line)"><el-icon><VideoPlay /></el-icon></button><label class="take-label"><span class="sr-only">第 {{ line.id }} 句表演版本</span><select v-model="takes[line.id]" @change="stopPlayback"><option value="directed">指导版</option><option v-if="manifest?.lines?.[line.id]?.neutral" value="neutral">无指导</option></select></label><button class="add-cue-button" :aria-label="`给第 ${line.id} 句加音效`" @click="selectedLineId = line.id; inspectorTab = 'sound'">+ 音效</button></div>
              </article>
            </div>
          </section>

          <section v-else-if="activeTab === 'voices'" class="voices-view">
            <header class="section-heading"><div><p class="night-kicker">CASTING ROOM</p><h2>选音色，也选表演方式。</h2></div></header>
            <p class="section-note">先听角色的指导版，再听候选音色。原候选组统一试音：“{{ manifest?.audition_text }}” 最终选择仍以你的听感为准。</p>
            <article v-for="actor in fixture.roles" :key="actor.id" class="actor-card" :style="{ '--actor': actor.color }"><div class="actor-avatar">{{ actor.initial }}</div><div><h3>{{ actor.name }} <span>{{ manifest?.roles?.[actor.id]?.label || manifest?.roles?.[actor.id]?.voice || '准备音色中' }}</span></h3><p>{{ actor.identity }}</p><small>{{ actor.direction }}</small><button class="text-action" :disabled="!ready || loadingAudio" @click="previewLine(lines.find(line => line.role === actor.id))"><el-icon><VideoPlay /></el-icon> 听角色台词</button></div></article>
            <h3 class="audition-title">备选声音 / 可直接试听</h3>
            <template v-if="freeCandidates?.auditions?.length">
              <p class="section-note">新免费模型 · 短句试音。三条使用相同新台词，可比较声音；原有角色配音继续保留。</p>
              <div class="audition-grid"><article v-for="voice in freeCandidates.auditions" :key="voice.id"><div><h4>{{ voice.label || voice.voice }}</h4><span>{{ voice.model }}</span></div><p>{{ voice.description }}</p><p class="audition-text">“{{ voice.text || freeCandidates.audition_text }}”</p><button :disabled="loadingAudio" @click="previewFile(voice.file, voice.duration || 15)"><el-icon><VideoPlay /></el-icon> 试听 {{ voice.voice }}</button></article></div>
              <h3 class="audition-title">已保存的原候选声音</h3>
            </template>
            <div class="audition-grid"><article v-for="voice in manifest?.auditions || []" :key="voice.id"><div><h4>{{ voice.label || voice.voice }}</h4><span>{{ voice.model }}</span></div><p>{{ voice.description }}</p><p v-if="voice.text" class="audition-text">“{{ voice.text || freeCandidates.audition_text }}”</p><button :disabled="loadingAudio" @click="previewFile(voice.file, voice.duration || 15)"><el-icon><VideoPlay /></el-icon> 试听 {{ voice.voice }}</button></article></div>
            <div class="voice-model-note"><el-icon><InfoFilled /></el-icon><p>指导版把表演指令单独交给支持该能力的模型。音效与导演备注不会作为台词朗读。试听音频的模型、音色、参数记录在导出的台本中。</p></div>
          </section>

          <section v-else class="prompt-view">
            <header class="section-heading"><div><p class="night-kicker">PRODUCTION GUIDE</p><h2>把你的故事，变成下一场戏。</h2></div></header>
            <p class="section-note">从小说原文开始，确认人物与台本，再为每句对白选择声音、编排音效并导出成片。</p>
            <div class="prompt-recipe"><h3>这段悬疑的导演约束</h3><ol><li>先列事实和每个人物已知的信息，禁止提前解释谜底。</li><li>把“看见蓝点”变成有动机的短对白，把重复叙述交给声音。</li><li>表演、音效、纯台词分开；音效写明进入时机与音量。</li><li>独立审查泄底、说话人、道具与声音时序，再修订。</li></ol></div>
            <label class="workbench-model">本次改编模型<select v-model="creationModel" aria-label="真实改编模型"><option value="qwen3.8-27b">qwen3.8-27b</option><option value="kimi-k3">kimi-k3</option></select></label><button class="night-primary workbench-cta" :disabled="creatingProject" @click="startRealProject">{{ creatingProject ? '创建项目…' : '用这段小说开始一次真实改编' }} <el-icon><TopRight /></el-icon></button><p v-if="isStaticDemo" class="section-note">真实改编需要本地工作台及你自己的模型配置。当前页面的试听、混音与导出无需 API Key。</p>
          </section>
        </main>

        <aside class="sound-inspector">
          <header><p class="night-kicker">SOUND DESIGN</p><h2>给这一刻，一个声音。</h2><p>选中台词，试听，再一键加入。</p></header>
          <label class="anchor-picker">当前台词<select v-model="selectedLineId"><option v-for="line in lines" :key="line.id" :value="line.id">{{ line.id }} · {{ role(line.role).name }} · {{ line.text.slice(0, 16) }}</option></select></label>
          <div class="cue-settings"><label>进入时机<CuePlacementSelect v-model="newPlacement" /></label><label>音量 <strong>{{ newGain }} dB</strong><input v-model.number="newGain" type="range" min="-32" max="0" aria-label="新增音效音量" /></label></div>
          <label class="effect-search"><el-icon><Search /></el-icon><input v-model="search" aria-label="搜索音效" placeholder="搜索雨声、门铃、脚步…" /></label>
          <div class="effects-list"><article v-for="effect in filteredEffects" :key="effect.id"><div><strong>{{ effect.label }}</strong><small>{{ effect.kind }} · {{ effect.seconds }}s</small></div><button :aria-label="`试听${effect.label}`" :disabled="loadingAudio" @click="previewFile(effect.file, effect.seconds)"><el-icon><VideoPlay /></el-icon></button><button :aria-label="`添加${effect.label}`" @click="addCue(effect)"><el-icon><Plus /></el-icon></button></article><p v-if="!filteredEffects.length" class="empty-note">没有找到，试试“雨”或“门”。</p></div>
          <section class="selected-cues"><h3>本句声音 <span>{{ lineCues(selectedLineId).length }}</span></h3><p v-if="!lineCues(selectedLineId).length" class="empty-note">为第 {{ selectedLineId }} 句添加一个声音。</p><article v-for="cue in lineCues(selectedLineId)" :key="cue.id"><div><strong>{{ cue.label }}</strong><small>{{ placementLabel(cue.placement) }} · {{ cue.gain }} dB</small></div><button :aria-label="`移除${cue.label}`" @click="removeCue(cue.id)"><el-icon><Close /></el-icon></button><input v-model.number="cue.gain" type="range" min="-36" max="0" :aria-label="`${cue.label}音量`" @input="stopPlayback" /></article></section>
          <p class="sound-credit">随附 CC0 音效与原创合成拟音。<a :href="assetUrl('sfx/credits.json')" target="_blank" rel="noopener">查看素材来源</a></p>
        </aside>
      </div>

      <section class="mix-desk" aria-label="成片混音与导出"><div class="mix-transport"><button class="mix-play" :aria-label="playing ? '暂停成片' : '播放成片'" :disabled="!ready || loadingAudio || staleLines.length > 0" @click="toggleMix"><el-icon><component :is="playing ? VideoPause : VideoPlay" /></el-icon></button><div><strong>{{ playing ? '正在播放' : '成片预览' }} <span>{{ formatTime(playhead) }} / {{ formatTime(schedule.duration) }}</span></strong><p>{{ staleLines.length ? `${staleLines.length} 句台词已修改，重新配音前不能导出旧音频。` : '你的台词版本、音效位置与音量，会一起进入导出成片。' }}</p></div><div class="mix-actions"><button :class="{ muted: muteEffects }" :aria-pressed="muteEffects" @click="muteEffects = !muteEffects; stopPlayback()"><el-icon><Headset /></el-icon>{{ muteEffects ? '纯人声' : '含音效' }}</button><button class="night-primary" aria-label="导出 WAV" :disabled="!ready || exporting || staleLines.length > 0" @click="exportMix"><el-icon><Download /></el-icon>{{ exporting ? '正在混音…' : '导出 WAV' }}</button></div></div>
        <input class="mix-seek" type="range" :min="0" :max="schedule.duration" :value="playhead" step="0.1" aria-label="成片播放进度" @input="seekMix" />
        <TimelineTracks :tracks="demoTracks" :duration-ms="schedule.duration*1000" :selected-line-id="selectedLineId" compact @select="selectDemoClip" />
      </section>
      <p v-if="error" class="night-error" role="alert">{{ error }}</p><p class="night-notice" role="status" aria-live="polite">{{ notice }}</p>
      <footer class="night-footer"><span>AURALIS · NOVEL → SCRIPT → PERFORMANCE → SOUND</span><span>声音由 AI 合成 · 原创演示故事 · 可编辑的制作过程</span></footer>
    </div>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowDown, Check, Close, Download, Headset, InfoFilled, Microphone, Plus, RefreshLeft, Search, TopRight, VideoPause, VideoPlay } from '@element-plus/icons-vue'
import ProductionSteps from '../components/production/ProductionSteps.vue'
import CuePlacementSelect from '../components/production/CuePlacementSelect.vue'
import TimelineTracks from '../components/production/TimelineTracks.vue'
import fixture from '../demo/suspense.json'
import { DemoMixer, makeSchedule } from '../demo/audioMixer'
import { IS_STATIC_DEMO } from '../api/config'
import { createProject } from '../api/project'
import { fetchLLMProviders, fetchTTSProviders } from '../api/provider'

const router = useRouter()
const creationModel = ref('qwen3.8-27b')
const isStaticDemo = IS_STATIC_DEMO
const base = new URL(`${import.meta.env.BASE_URL}demo-night/`, document.baseURI)
const assetUrl = file => new URL(file, base).href
const mixer = new DemoMixer(base)
const key = 'auralis-night-delivery-v1'
const clone = value => JSON.parse(JSON.stringify(value))
const lines = ref(clone(fixture.lines)), cues = ref(clone(fixture.cues))
const takes = reactive(Object.fromEntries(fixture.lines.map(line => [line.id, 'directed'])))
const manifest = ref(null), freeCandidates = ref(null), activeTab = ref('script'), inspectorTab = ref('sound')
const selectedLineId = ref('04'), newPlacement = ref('before'), newGain = ref(-16), search = ref('')
const loadingAudio = ref(false), playing = ref(false), playhead = ref(0), muteEffects = ref(false), exporting = ref(false), creatingProject = ref(false)
const error = ref(''), notice = ref(''), mode = ref('mix')
let frame = 0, noticeTimer, previewDuration = 0, operation = 0
const tabs = [{ id: 'script', number: '01', label: '台本与表演' }, { id: 'voices', number: '02', label: '角色试音' }, { id: 'production', number: '03', label: '开始制作' }]
const effects = [
  { id: 'rain', label: '雨敲窗', file: 'sfx/rain.mp3', kind: '环境 · 循环', seconds: 12 },
  { id: 'doorbell', label: '公寓门铃', file: 'sfx/doorbell.mp3', kind: '动作', seconds: 2 },
  { id: 'paper', label: '纸张翻动', file: 'sfx/paper.mp3', kind: '近景', seconds: 1 },
  { id: 'knock', label: '敲门 · 一慢两快', file: 'sfx/knock.wav', kind: '节奏线索', seconds: 2.6 },
  { id: 'vibration', label: '手机振动', file: 'sfx/vibration.wav', kind: '近景', seconds: 1.8 },
  { id: 'steps', label: '木地板脚步', file: 'sfx/steps.mp3', kind: '动作', seconds: 1 },
  { id: 'clock', label: '钟表滴答', file: 'sfx/clock.mp3', kind: '环境 · 循环', seconds: 4 },
]
const filteredEffects = computed(() => effects.filter(item => `${item.label}${item.kind}`.includes(search.value.trim())))
const ready = computed(() => lines.value.every(line => manifest.value?.lines?.[line.id]?.directed?.file))
const hasAllNeutral = computed(() => lines.value.every(line => manifest.value?.lines?.[line.id]?.neutral?.file))
const allDirected = computed(() => Object.values(takes).every(take => take === 'directed'))
const allNeutral = computed(() => Object.values(takes).every(take => take === 'neutral'))
const schedule = computed(() => makeSchedule(lines.value, cues.value, manifest.value, takes, effects, muteEffects.value))
const demoTracks = computed(() => ['voice','sfx'].map(kind=>({key:kind,label:kind==='voice'?'人声':'音效',clips:schedule.value.clips.filter(clip=>clip.kind===kind).map(clip=>({...clip,line_id:clip.kind==='voice'?clip.id:null,start_ms:clip.start*1000,duration_ms:clip.duration*1000,line:{text_content:clip.label,status:'done'}}))})))
function selectDemoClip(clip){if(clip.line_id)selectedLineId.value=clip.line_id;jumpTo(clip.start_ms/1000)}
const staleLines = computed(() => lines.value.filter(isStale))
const currentLineId = computed(() => mode.value === 'mix' ? schedule.value.clips.find(clip => clip.kind === 'voice' && clip.start <= playhead.value && clip.start + clip.duration > playhead.value)?.id : null)
const role = id => fixture.roles.find(item => item.id === id) || fixture.roles[0]
const lineCues = id => cues.value.filter(cue => cue.anchor === id)
const placementLabel = value => ({ before: '台词前', with: '同时', after: '台词后' })[value]
function isStale(line) { return fixture.lines.find(item => item.id === line.id)?.text !== line.text }
function formatTime(seconds) { const value = Math.max(0, Math.floor(seconds || 0)); return `${String(Math.floor(value / 60)).padStart(2, '0')}:${String(value % 60).padStart(2, '0')}` }
function say(text) { notice.value = text; clearTimeout(noticeTimer); noticeTimer = setTimeout(() => { notice.value = '' }, 5000) }

onMounted(async () => {
  try {
    const saved = JSON.parse(localStorage.getItem(key) || 'null')
    if (saved?.id === fixture.id) {
      // Only restore known lines and valid cue references; stale audio is gated below.
      for (const line of lines.value) { const savedLine = saved.lines?.find(item => item.id === line.id); if (typeof savedLine?.text === 'string') line.text = savedLine.text }
      if (Array.isArray(saved.cues)) cues.value = saved.cues.map(cue => cue.id === 'rain' ? { ...cue, follow_scene: true } : cue).filter(cue => effects.some(effect => effect.id === cue.asset) && lines.value.some(line => line.id === cue.anchor) && ['before', 'with', 'after'].includes(cue.placement) && Number.isFinite(cue.duration) && cue.duration > 0 && cue.duration <= 120 && Number.isFinite(cue.gain) && cue.gain >= -36 && cue.gain <= 0)
      for (const id of Object.keys(takes)) if (['directed', 'neutral'].includes(saved.takes?.[id])) takes[id] = saved.takes[id]
    }
  } catch { /* A damaged or unavailable browser store must not prevent the demo. */ }
  try { const response = await fetch(assetUrl('manifest.json')); if (!response.ok) throw new Error(); manifest.value = await response.json(); if (!ready.value) throw new Error(); for (const id of Object.keys(takes)) if (!manifest.value.lines[id]?.[takes[id]]) takes[id] = 'directed' } catch { error.value = '样片音频尚未就绪。你仍可编辑台本与音效安排。' }
  try { const response = await fetch(assetUrl('free-candidates.json')); if (response.ok) freeCandidates.value = await response.json() } catch { /* New auditions are independent of the preserved production takes. */ }
})
watch([lines, cues, takes], () => {
  try { localStorage.setItem(key, JSON.stringify({ id: fixture.id, lines: lines.value, cues: cues.value, takes })) } catch { say('浏览器存储不可用，请导出台本保存修改。') }
}, { deep: true })
onBeforeUnmount(() => { operation++; cancelAnimationFrame(frame); clearTimeout(noticeTimer); mixer.dispose() })

function stopPlayback() { operation++; mixer.stop(); cancelAnimationFrame(frame); playing.value = false; loadingAudio.value = false }
function tick() { playhead.value = Math.max(0, mixer.ctx.currentTime - mixer.startedAt); const end = mode.value === 'mix' ? schedule.value.duration : previewDuration; if (playhead.value >= end) { stopPlayback(); playhead.value = 0; return } frame = requestAnimationFrame(tick) }
async function startSchedule(value, offset = 0, playbackMode = 'mix') {
  stopPlayback(); const token = operation; mode.value = playbackMode; previewDuration = value.duration; loadingAudio.value = true; error.value = ''
  try { const ctx = await mixer.play(value, offset); if (!ctx || operation !== token) return; playing.value = true; tick() } catch (err) { if (operation === token) error.value = err.message || '音频播放失败，请重试。' } finally { if (operation === token) loadingAudio.value = false }
}
function toggleMix() { if (staleLines.value.length || !ready.value) { say('请还原修改过的台词，或在真实工作台重新配音。'); return } if (playing.value && mode.value === 'mix') { stopPlayback(); return } const offset = mode.value === 'mix' && playhead.value < schedule.value.duration ? playhead.value : 0; startSchedule(schedule.value, offset) }
function previewLine(line) { if (!line || isStale(line)) return; const take = manifest.value?.lines?.[line.id]?.[takes[line.id] || 'directed']; if (take) previewFile(take.file, take.duration) }
function previewFile(file, duration) { startSchedule({ duration, clips: [{ id: file, kind: 'voice', file, start: 0, duration, gain: 0 }] }, 0, 'preview') }
function seekMix(event) { const resume = playing.value; stopPlayback(); mode.value = 'mix'; playhead.value = Number(event.target.value); if (resume && ready.value && !staleLines.value.length) startSchedule(schedule.value, playhead.value) }
function jumpTo(seconds) { stopPlayback(); mode.value = 'mix'; playhead.value = seconds; say(`已定位到 ${formatTime(seconds)}，点击播放试听。`) }
function setAllTakes(take) { stopPlayback(); playhead.value = 0; Object.keys(takes).forEach(id => { takes[id] = take }); say(take === 'directed' ? '已采用导演指导版，试听与导出将使用此版本。' : '已切换无指导对照，模型、角色和台词保持一致。') }
function addCue(effect) { stopPlayback(); cues.value.push({ id: `cue-${globalThis.crypto.randomUUID()}`, asset: effect.id, anchor: selectedLineId.value, placement: newPlacement.value, gain: newGain.value, duration: effect.seconds, label: effect.label }); say(`已在第 ${selectedLineId.value} 句${placementLabel(newPlacement.value)}加入「${effect.label}」。`) }
function removeCue(id) { stopPlayback(); cues.value = cues.value.filter(cue => cue.id !== id); say('已移除音效。') }
function restoreLine(line) { stopPlayback(); line.text = fixture.lines.find(item => item.id === line.id).text }
